import{_ as r,o as a,c as d,a2 as l}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"عدلیہ کا نظام اور فیصلے کا طریقہ کار","description":"","frontmatter":{},"headers":[],"relativePath":"ur/48-司法体系与裁决机制.md","filePath":"ur/48-司法体系与裁决机制.md","lastUpdated":null}'),o={name:"ur/48-司法体系与裁决机制.md"};function i(e,t,n,h,s,g){return a(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="عدلیہ-کا-نظام-اور-فیصلے-کا-طریقہ-کار" tabindex="-1">عدلیہ کا نظام اور فیصلے کا طریقہ کار <a class="header-anchor" href="#عدلیہ-کا-نظام-اور-فیصلے-کا-طریقہ-کار" aria-label="Permalink to &quot;عدلیہ کا نظام اور فیصلے کا طریقہ کار&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>48</td></tr><tr><td>ماڈیول</td><td>قانونی نظام اور گورننس کا فریم ورک</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>سمبیوسس عدالت، عدلیہ کی آزادی، فیصلے کا طریقہ کار، بین نسلی انصاف، غیر آئینی جائزہ</td></tr></tbody></table><h2 id="أولاً-عدلیہ-کے-نظام-کی-حیثیت-اور-اصول" tabindex="-1">أولاً. عدلیہ کے نظام کی حیثیت اور اصول <a class="header-anchor" href="#أولاً-عدلیہ-کے-نظام-کی-حیثیت-اور-اصول" aria-label="Permalink to &quot;أولاً. عدلیہ کے نظام کی حیثیت اور اصول&quot;">​</a></h2><p>عدلیہ کا نظام اینکر سمبیوسس تہذیب کے گورننس کے فریم ورک کا ایک اہم ستون ہے، اور یہ قانون سازی کی طاقت (اینکر کونسل)، انتظامی طاقت (سمبیوسس ایگزیکٹو کمیٹی) کے ساتھ برابری کا حامل ہے، اور آزادانہ طور پر انصاف کی طاقت کا استعمال کرتا ہے۔ 《سمبیوسس آئین》 &quot;تین طاقتوں کی تقسیم اور توازن&quot; کے گورننس کے ڈھانچے کو قائم کرتا ہے، اور عدلیہ کا نظام آئین کی وقار کو برقرار رکھنے، تمام زندگیوں کے حقوق کی حفاظت، اور سماجی تنازعات کے حل کی آخری دفاعی لائن ہے۔</p><p>ہینگیوانژو کے عدلیہ کا نظام درج ذیل بنیادی اصول قائم کرتا ہے:</p><table tabindex="0"><thead><tr><th>اصول</th><th>مواد</th></tr></thead><tbody><tr><td>عدلیہ کی آزادی کا اصول</td><td>عدالتیں قانون کے مطابق آزادانہ طور پر انصاف کی طاقت کا استعمال کرتی ہیں، اور انتظامی اداروں، سماجی تنظیموں اور افراد کی مداخلت سے آزاد ہیں</td></tr><tr><td>عدلیہ کے انصاف کا اصول</td><td>انصاف کی سرگرمیاں حقائق پر مبنی ہیں اور قانون کو معیار کے طور پر لیتی ہیں، اور طریقہ کار کے انصاف اور بنیادی انصاف کو یقینی بناتی ہیں</td></tr><tr><td>عدلیہ کی کھلے پن کا اصول</td><td>انصاف کی سرگرمیاں قانون کے مطابق کھلی طور پر کی جاتی ہیں، اور فیصلے کی تحریریں شائع کی جاتی ہیں، اور سماجی نگرانی قبول کرتی ہیں</td></tr><tr><td>تمام نسلوں کی مساوات کا اصول</td><td>تمام زندگییں انصاف کے سامنے برابر ہیں، اور قانون کے اطلاق میں نسل، سادھنہ کی سطح، یا اصل میں کوئی فرق نہیں ہے</td></tr><tr><td>عدلیہ کی سہولت کا اصول</td><td>عدلیہ کی خدمات کو تمام زندگیوں کے لیے آسان بنانا چاہیے، مقدمے کی لاگت کو کم کرنا چاہیے، اور تنازعات کے حل کے متعدد راستے فراہم کرنے چاہیے</td></tr><tr><td>حتمی فیصلے کا اصول</td><td>دو بار انصاف کے حتمی نظام کا اطلاق ہوتا ہے، اور حتمی فیصلے حتمی اثر رکھتے ہیں، اور عدلیہ کے اختیار کو برقرار رکھتے ہیں</td></tr></tbody></table><h2 id="ثانياً-عدالتوں-کی-تنظیمی-نظام" tabindex="-1">ثانياً. عدالتوں کی تنظیمی نظام <a class="header-anchor" href="#ثانياً-عدالتوں-کی-تنظیمی-نظام" aria-label="Permalink to &quot;ثانياً. عدالتوں کی تنظیمی نظام&quot;">​</a></h2><p>اینکر سمبیوسس تہذیب کے عدالتوں کی تنظیمی نظام چار سطحوں میں تقسیم ہے، اور دو بار انصاف کے حتمی نظام کا اطلاق ہوتا ہے:</p><table tabindex="0"><thead><tr><th>سطح</th><th>عدالت کا نام</th><th>دائرہ اختیار</th><th>بنیادی کام</th></tr></thead><tbody><tr><td>پہلی سطح</td><td>بنیادی سمبیوسس عدالت</td><td>ضلع/چھوٹا位面</td><td>پہلی بار کے دیوانی، فوجداری، انتظامی مقدمات کی سماعت، اور سادہ تنازعات کا حل</td></tr><tr><td>دوسری سطح</td><td>علاقائی سمبیوسس عدالت</td><td>شہر/علاقہ/درمیانہ位面</td><td>پہلی بار کے بڑے مقدمات اور بنیادی عدالت کے فیصلے کے خلاف اپیل کے مقدمات کی سماعت</td></tr><tr><td>تیسری سطح</td><td>位面 سمبیوسس عدالت</td><td>بڑا位面/位面 گروپ</td><td>پہلی بار کے خاص طور پر بڑے مقدمات اور علاقائی عدالت کے فیصلے کے خلاف اپیل کے مقدمات کی سماعت</td></tr><tr><td>چوتھی سطح</td><td>سمبیوسس سپریم کورٹ</td><td>پوری کائنات</td><td>پہلی بار کے آئینی مقدمات،位面 عدالت کے فیصلے کے خلاف اپیل کے مقدمات، اور غیر آئینی جائزہ</td></tr></tbody></table><p>اس کے علاوہ، ضرورت کے مطابق خصوصی عدالتیں قائم کی جاتی ہیں:</p><ul><li><strong>سادھنہ تنازعات کی عدالت</strong>: خاص طور پر سادھنہ وسائل کے تنازعات، سادھنہ نقصان کے معاوضے، سادھنہ اخلاقی تنازعات وغیرہ کے مقدمات کی سماعت کرتی ہے۔</li><li><strong>بین نسلی عدالت</strong>: خاص طور پر مختلف نسلوں کے درمیان تنازعات سے متعلق مقدمات کی سماعت کرتی ہے، اور ہر نسل کے ججز سے لیس ہے۔</li><li><strong>位面 تجارتی عدالت</strong>: خاص طور پر بین位面 تجارتی تنازعات اور یکجا اختصاص مخالف مقدمات کی سماعت کرتی ہے۔</li><li><strong>عجیب زندگی کی عدالت</strong>: خاص طور پر عجیب زندگی، عجیب توانائی، اور تاریک متبادل جسم سے متعلق خصوصی مقدمات کی سماعت کرتی ہے۔</li></ul><h2 id="ثالثاً-ججوں-کا-نظام" tabindex="-1">ثالثاً. ججوں کا نظام <a class="header-anchor" href="#ثالثاً-ججوں-کا-نظام" aria-label="Permalink to &quot;ثالثاً. ججوں کا نظام&quot;">​</a></h2><p>جج عدلیہ کی طاقت کے استعمال کرنے والے ہیں، اور ان کی قابلیت اور آزادی براہ راست عدلیہ کے انصاف سے متعلق ہے:</p><ol><li><strong>ججوں کی تقرری کی شرائط</strong>: ججوں کے پاس اچھا اخلاق، مضبوط قانونی علم، اور بھرپور عملی تجربہ ہونا چاہیے، اور غیر ملکی نسل کے ججوں کو اپنی نسل کی ثقافت اور جسمانی خصوصیات سے بھی واقف ہونا چاہیے۔</li><li><strong>ججوں کے انتخاب کا عمل</strong>: ججوں کو آزاد جج انتخاب کمیٹی کے ذریعے نامزد کیا جاتا ہے اور اینکر کونسل کے ذریعے تقرر کیا جاتا ہے، اور انتخاب کے عمل کے انصاف اور پیشہ ورانہ کو یقینی بنایا جاتا ہے۔</li><li><strong>ججوں کی شناخت کی تحفظ</strong>: ججوں کو قانونی وجہ کے بغیر، قانونی عمل کے بغیر، عہدے سے ہٹایا، عہدہ کم کیا، برخاست کیا، یا سزا نہیں دی جا سکتی، اور جج آزادانہ طور پر فیصلہ کر سکتے ہیں۔</li><li><strong>ججوں کی اجتناب کا نظام</strong>: جج جس کا مقدمے کی فریق یا مقدمے کے نتیجے سے مفاد کا تعلق ہو، اسے اجتناب کرنا چاہیے، اور وہ مقدمے کی سماعت میں حصہ نہیں لے سکتا۔</li><li><strong>ججوں کی سزا کا نظام</strong>: جج جو بدعنوانی، رشوت، دھوکہ دہی، فیصلے میں بے وفائی وغیرہ کا عمل کرتا ہے، اسے قانون کے مطابق سزا دی جائے گی، اور جو جرم تشکیل دے گا اسے فوجداری ذمہ داری عائد کی جائے گی۔</li><li><strong>غیر ملکی نسل کے ججوں کا کوٹہ</strong>: ہر سطح کی عدالتوں میں ایک مخصوص تناسب کے غیر ملکی نسل کے ججز سے لیس ہونا چاہیے، اور فیصلے میں ہر نسل کی ثقافت اور قانونی علم کو مدنظر رکھا جائے۔</li></ol><h2 id="رابعاً-مقدمے-کا-عمل" tabindex="-1">رابعاً. مقدمے کا عمل <a class="header-anchor" href="#رابعاً-مقدمے-کا-عمل" aria-label="Permalink to &quot;رابعاً. مقدمے کا عمل&quot;">​</a></h2><h3 id="_1-دیوانی-مقدمے-کا-عمل" tabindex="-1">(1) دیوانی مقدمے کا عمل <a class="header-anchor" href="#_1-دیوانی-مقدمے-کا-عمل" aria-label="Permalink to &quot;(1) دیوانی مقدمے کا عمل&quot;">​</a></h3><p>دیوانی مقدمے میں &quot;نہ کہے تو نہ سنیں&quot; کا اصول لاگو ہوتا ہے، اور عمل میں شامل ہیں:</p><ol><li><strong>مقدمہ دائر اور قبولیت</strong>: مدعی جس کی عدالت میں دائرہ اختیار ہے وہاں مقدمہ دائر کرتا ہے، اور عدالت جائزہ کے بعد فیصلہ کرتی ہے کہ قبول کرے یا نہیں۔</li><li><strong>سماعت سے پہلے تیاری</strong>: عدالت مدعا علیہ کو مقدمے کی کاپی بھیجتی ہے، ثبوت کے تبادلے کا اہتمام کرتی ہے، اور تنازعہ کے نکات کا تعین کرتی ہے۔</li><li><strong>عدالت میں سماعت</strong>: عدالت کی تحقیقات، عدالت کی بحث، فریق کی آخری بیان، اور ثالثی کو ترجیح دی جاتی ہے۔</li><li><strong>فیصلہ اور عملدرآمد</strong>: عدالت قانون کے مطابق فیصلہ دیتی ہے، اور فریق جو غیر مطمئن ہو وہ قانونی مدت میں اپیل کر سکتا ہے۔ موثر فیصلے کو عملدرآمد ادارے کے ذریعے جبری طور پر عملدرآمد کیا جاتا ہے۔</li></ol><h3 id="_2-فوجداری-مقدمے-کا-عمل" tabindex="-1">(2) فوجداری مقدمے کا عمل <a class="header-anchor" href="#_2-فوجداری-مقدمے-کا-عمل" aria-label="Permalink to &quot;(2) فوجداری مقدمے کا عمل&quot;">​</a></h3><p>فوجداری مقدمے میں &quot;بے گناہ قیاس&quot; کا اصول لاگو ہوتا ہے، اور عمل میں شامل ہیں:</p><ol><li><strong>مقدمہ درج اور تحقیقات</strong>: تحقیقات ادارہ جرم کے عمل میں مقدمہ درج کرکے تحقیقات کرتا ہے، ثبوت اکٹھا کرتا ہے، اور جبری اقدامات اٹھاتا ہے۔</li><li><strong>جائزہ اور مقدمہ دائر</strong>: استغاثہ ادارہ تحقیقات کے نتائج کا جائزہ لیتا ہے، اور فیصلہ کرتا ہے کہ عوامی مقدمہ دائر کرے یا نہیں۔</li><li><strong>سماعت</strong>: عدالت عدالت میں سماعت کرتی ہے، اور استغاثہ اور دفاع دونوں فریق ثبوت پیش اور جائزہ لیتے ہیں، اور عدالت قانون کے مطابق فیصلہ دیتی ہے۔</li><li><strong>عملدرآمد</strong>: موثر فیصلے کو عملدرآمد ادارے کے ذریعے عملدرآمد کیا جاتا ہے، اور اس میں سزا کا عملدرآمد اور منسلک دیوانی معاوضے کا عملدرآمد شامل ہے۔</li></ol><h3 id="_3-انتظامی-مقدمے-کا-عمل" tabindex="-1">(3) انتظامی مقدمے کا عمل <a class="header-anchor" href="#_3-انتظامی-مقدمے-کا-عمل" aria-label="Permalink to &quot;(3) انتظامی مقدمے کا عمل&quot;">​</a></h3><p>شہری، قانونی شخص، یا دیگر تنظیمیں جو سمجھتی ہیں کہ انتظامی ادارے کا انتظامی عمل ان کے قانونی حقوق کی خلاف ورزی کرتا ہے، ان کے پاس عدالت میں انتظامی مقدمہ دائر کرنے کا حق ہے۔ انتظامی مقدمے میں &quot;ثبوت کی ذمہ داری الٹنا&quot; لاگو ہوتا ہے، اور مدعا علیہ انتظامی ادارے کو اپنے انتظامی عمل کی قانونی حیثیت کے لیے ثبوت کی ذمہ داری اٹھانی ہوگی۔</p><h3 id="_4-آئینی-مقدمے-کا-عمل" tabindex="-1">(4) آئینی مقدمے کا عمل <a class="header-anchor" href="#_4-آئینی-مقدمے-کا-عمل" aria-label="Permalink to &quot;(4) آئینی مقدمے کا عمل&quot;">​</a></h3><p>تمام زندگی جو سمجھتی ہیں کہ ان کے آئینی بنیادی حقوق کی خلاف ورزی ہوئی ہے، اور دوسرے امدادی راستوں کو مکمل طور پر استعمال کر چکے ہیں، وہ براہ راست آئین کی بنیاد پر سمبیوسس سپریم کورٹ میں آئینی مقدمہ دائر کر سکتے ہیں۔ آئینی مقدمہ آئینی حقوق کی حفاظت کا آخری امدادی راستہ ہے۔</p><h2 id="خامساً-متعدد-تنازعات-کے-حل-کا-طریقہ-کار" tabindex="-1">خامساً. متعدد تنازعات کے حل کا طریقہ کار <a class="header-anchor" href="#خامساً-متعدد-تنازعات-کے-حل-کا-طریقہ-کار" aria-label="Permalink to &quot;خامساً. متعدد تنازعات کے حل کا طریقہ کار&quot;">​</a></h2><p>عدلیہ کے بوجھ کو کم کرنے اور تنازعات کے حل کی کارکردگی کو بڑھانے کے لیے، ریاست متعدد تنازعات کے حل کا طریقہ کار قائم کرتی ہے:</p><table tabindex="0"><thead><tr><th>طریقہ کار</th><th>اطلاق کا دائرہ</th><th>اثر</th></tr></thead><tbody><tr><td>مذاکرات اور معاہدہ</td><td>تمام دیوانی تنازعات</td><td>فریق رضامندی سے پورا کرتے ہیں، اور جبری عملدرآمد کی طاقت نہیں ہے</td></tr><tr><td>عوامی ثالثی</td><td>لوک تنازعات، پڑوسی تنازعات</td><td>ثالثی کے معاہدے کو عدالت کی عدلیہ کی تصدیق کے بعد جبری عملدرآمد کی طاقت حاصل ہوتی ہے</td></tr><tr><td>انتظامی ثالثی</td><td>انتظامی تنازعات، دیوانی معاوضے کے تنازعات</td><td>ثالثی کے معاہدے کا معاہدہ کا اثر ہوتا ہے</td></tr><tr><td>ثالثی (آربیٹریشن)</td><td>تجارتی تنازعات، مزدور تنازعات</td><td>ثالثی کے فیصلے کی جبری عملدرآمد کی طاقت ہوتی ہے، اور ایک بار ثالثی حتمی ہوتی ہے</td></tr><tr><td>عدلیہ کا فیصلہ</td><td>تمام تنازعات</td><td>حتمی فیصلے کی حتمی جبری عملدرآمد کی طاقت ہوتی ہے</td></tr></tbody></table><p>ریاست فریق کو ترجیح دے کر غیر مقدمہ طریقے سے تنازعات حل کرنے کی ترغیب دیتی ہے، اور عدالتوں کو بھی مقدمے کے عمل میں ثالثی کرنی چاہیے۔</p><h2 id="سادساً-غیر-آئینی-جائزے-کا-نظام" tabindex="-1">سادساً. غیر آئینی جائزے کا نظام <a class="header-anchor" href="#سادساً-غیر-آئینی-جائزے-کا-نظام" aria-label="Permalink to &quot;سادساً. غیر آئینی جائزے کا نظام&quot;">​</a></h2><p>غیر آئینی جائزہ عدلیہ کے نظام کے لیے آئین کے اختیار کو برقرار رکھنے کا ایک اہم نظام ہے:</p><ol><li><strong>جائزے کا موضوع</strong>: سمبیوسس سپریم کورٹ غیر آئینی جائزے کا واحد موضوع ہے، اور خاص طور پر غیر آئینی جائزے کے لیے آئینی انصاف کی کمرہ قائم کرتی ہے۔</li><li><strong>جائزے کا دائرہ</strong>: آئین، انتظامی ضوابط، مقامی ضوابط، خود مختار ضوابط، عدلیہ کی تشریحات وغیرہ معیاری دستاویزات آئین کی خلاف ورزی کرتے ہیں یا نہیں۔</li><li><strong>جائزے کا آغاز</strong>: عدالت مقدمے کی سماعت کے دوران فعال طور پر شروع کر سکتی ہے، یا تمام زندگی، تنظیمیں، یا ریاستی ادارے جائزے کی درخواست دے سکتے ہیں۔</li><li><strong>جائزے کا اثر</strong>: جائزے کے بعد آئین کی خلاف ورزی قرار پائی جانے والی معیاری دستاویزات، اشاعت کے دن سے غیر موثر، اور مزید فیصلے کی بنیاد کے طور پر استعمال نہیں کی جا سکتیں۔</li><li><strong>جائزے کا معیار</strong>: آئین کے متن اور آئینی اصولوں کی بنیاد پر، قانونی نظام کے استحکام اور آئین کی موافقت کو مدنظر رکھنا۔</li></ol><h2 id="سابعاً-عدلیہ-کی-تحفظ-اور-نگرانی" tabindex="-1">سابعاً. عدلیہ کی تحفظ اور نگرانی <a class="header-anchor" href="#سابعاً-عدلیہ-کی-تحفظ-اور-نگرانی" aria-label="Permalink to &quot;سابعاً. عدلیہ کی تحفظ اور نگرانی&quot;">​</a></h2><ul><li><strong>عدلیہ کے بجٹ کی تحفظ</strong>: عدالتوں کے بجٹ کو عوامی جمع سے الگ سے یقینی بنایا جاتا ہے، اور مقامی انتظامی اداروں کے کنٹرول میں نہیں ہے، اور عدلیہ کی آزادی کی معاشی بنیاد کو یقینی بنایا جاتا ہے۔</li><li><strong>عدلیہ کی انفارمیشن ٹیکنالوجی</strong>: بین位面 مواصلاتی ٹیکنالوجی کا استعمال کرتے ہوئے عدلیہ کی معلومات کا نظام قائم کرنا، اور مقدمہ درج، سماعت، عملدرآمد کے مکمل عمل کی انفارمیشن ٹیکنالوجی کو实现 کرنا، اور عدلیہ کی کارکردگی کو بڑھانا۔</li><li><strong>عدلیہ کی نگرانی</strong>: اینکر نگرانی کمیٹی عدلیہ کی سرگرمیوں کی نگرانی کرتی ہے، اور عوام اور میڈیا عدلیہ کی سرگرمیوں پر رائے عامہ کی نگرانی کر سکتے ہیں، لیکن انصاف کی آزادی میں مداخلت نہیں کر سکتے۔</li><li><strong>عدلیہ کی امداد</strong>: معاشی مشکلات میں مبتلا فریق کو قانونی امداد اور مقدمے کی لاگت میں کمی یا معافی فراہم کرنا، اور یقینی بنانا کہ وہ معاشی وجوہات کی بنا پر عدلیہ کی امداد کا موقع نہیں کھوتیں۔</li></ul><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>عدلیہ کا نظام اینکر سمبیوسس تہذیب کے قانون کی حکمرانی کی آخری تحفظ ہے۔ یہ چار سطحوں کی عدالتوں کا نظام قائم کرکے، عدلیہ کی آزادی کا اطلاق کرکے، متعدد تنازعات کے حل کا طریقہ کار اور غیر آئینی جائزے کا نظام قائم کرکے، یقینی بناتا ہے کہ قانون کو منصفانہ طریقے سے لاگو کیا جائے، تمام زندگیوں کے حقوق کو مؤثر طریقے سے امداد ملے، اور تمام نسلوں کی مشترکہ ترقی کے لیے قانون کی حکمرانی کی دفاعی لائن کو مضبوط کیا جائے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>40-共生宪法总纲 (سمبیوسس آئین کے بنیادی اصول)</li><li>49-治理框架与权力制衡 (گورننس کا فریم ورک اور طاقتوں کا توازن)</li><li>58-双魂伦理准则 (دوہری روح اخلاقی ضوابط)</li><li>03-共生文明宪章 (سمبیوسس تہذیب کا چارٹر)</li></ul>',38)])])}const c=r(o,[["render",i]]);export{b as __pageData,c as default};
